// Package assets exposes the generated frontend files embedded in the binary.
package assets

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"io/fs"
	"net/http"
	"strings"
)

// Files contains production-ready assets generated by the frontend toolchain.
//
//go:embed dist
var files embed.FS

// Handler serves embedded assets without requiring files beside the binary.
//
// Embedded files carry no modification time, so the standard file server cannot
// offer cache validators. Without them browsers refetch the stylesheet, the
// script, and the webfonts on every navigation, which renders text in a
// fallback font until the webfont arrives. Assets therefore get a content
// ETag and a freshness window that still revalidates once it expires. The
// requests arrive with the "/assets/" prefix already stripped by the router.
func Handler() http.Handler {
	dist, err := fs.Sub(files, "dist")
	if err != nil {
		panic("create embedded asset filesystem: " + err.Error())
	}

	etags, err := assetETags(dist)
	if err != nil {
		panic("index embedded assets: " + err.Error())
	}

	server := http.FileServer(http.FS(dist))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if etag, ok := etags[strings.TrimPrefix(r.URL.Path, "/")]; ok {
			w.Header().Set("Cache-Control", "public, max-age=3600")
			w.Header().Set("ETag", etag)
		}
		server.ServeHTTP(w, r)
	})
}

func assetETags(dist fs.FS) (map[string]string, error) {
	etags := make(map[string]string)
	err := fs.WalkDir(dist, ".", func(name string, entry fs.DirEntry, err error) error {
		if err != nil || entry.IsDir() {
			return err
		}
		content, err := fs.ReadFile(dist, name)
		if err != nil {
			return err
		}
		sum := sha256.Sum256(content)
		etags[name] = `"` + hex.EncodeToString(sum[:16]) + `"`
		return nil
	})
	if err != nil {
		return nil, err
	}
	return etags, nil
}
